// Extract sender email and normalize for lead matching
const email = $input.item.json;

// Parse sender — IMAP returns 'from' as address string or object
let senderEmail = '';
let senderName = '';

if (email.from) {
  // Handle both 'Name <email>' format and plain email
  const fromStr = typeof email.from === 'string' ? email.from : (email.from.text || email.from.value?.[0]?.address || '');
  const match = fromStr.match(/<([^>]+)>/);
  senderEmail = match ? match[1].toLowerCase().trim() : fromStr.toLowerCase().trim();
  const nameMatch = fromStr.match(/^([^<]+)</);
  senderName = nameMatch ? nameMatch[1].trim() : '';
}

// Skip system emails, bounces, noreply
const skipPatterns = ['noreply', 'no-reply', 'mailer-daemon', 'postmaster', 'lnlautomations.com', 'lnlcreatives.com'];
const isSystemEmail = skipPatterns.some(p => senderEmail.includes(p));

return {
  json: {
    senderEmail,
    senderName,
    subject: email.subject || '(no subject)',
    date: email.date || new Date().toISOString(),
    textBody: (email.text || '').substring(0, 2000),
    htmlBody: (email.html || '').substring(0, 5000),
    isSystemEmail,
    messageId: email.messageId || '',
    inReplyTo: email.inReplyTo || ''
  }
};

// Match inbound sender email to a lead in the pipeline
const items = $input.all();
if (items.length < 2) {
  return [{ json: { matched: false, reason: 'No sheet data returned' } }];
}

// First item is the email data passed through, rest are sheet rows
// Actually: the Lookup node replaces $json with sheet data.
// We need the previous node's data. Use $('Extract Sender & Match Lead') to get it.
// In n8n code nodes after a Sheets read, $input contains sheet rows.

// The sender info was passed through the filter node.
// We need to access it via $('Filter System Emails').first().json
let senderEmail, senderName, subject, textBody, htmlBody, date;
try {
  const emailData = $('Filter System Emails').first().json;
  senderEmail = emailData.senderEmail;
  senderName = emailData.senderName;
  subject = emailData.subject;
  textBody = emailData.textBody;
  htmlBody = emailData.htmlBody;
  date = emailData.date;
} catch(e) {
  return [{ json: { matched: false, reason: 'Could not read email data: ' + e.message } }];
}

// Sheet rows are in $input
const rows = items.map(i => i.json);

// Find matching lead by email (case-insensitive)
const matchedLead = rows.find(row => {
  const leadEmail = (row['Email'] || '').toLowerCase().trim();
  return leadEmail === senderEmail;
});

if (!matchedLead) {
  return [{ json: {
    matched: false,
    senderEmail,
    senderName,
    subject,
    textBody,
    htmlBody,
    date,
    reason: 'No matching lead found in pipeline'
  }}];
}

return [{ json: {
  matched: true,
  senderEmail,
  senderName,
  subject,
  textBody,
  htmlBody,
  date,
  leadId: matchedLead['Lead ID'] || '',
  leadName: matchedLead['Full Name'] || matchedLead['Business Name'] || '',
  businessName: matchedLead['Business Name'] || '',
  currentStatus: matchedLead['Status'] || '',
  outreachStatus: matchedLead['Outreach Status'] || '',
  industry: matchedLead['Industry'] || '',
  rowNumber: matchedLead['row_number'] || matchedLead['__row'] || ''
}}];

// Format the forwarded email with lead context
const d = $input.item.json;

const subject = '[LEAD REPLY] ' + (d.businessName || d.senderName || d.senderEmail) + ' — ' + d.subject;

let html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">';
html += '<div style="background:#28a745;color:white;padding:12px 20px;border-radius:6px 6px 0 0">';
html += '<h2 style="margin:0">Lead Reply Received</h2>';
html += '</div>';
html += '<div style="border:1px solid #dee2e6;border-top:none;padding:20px">';

// Lead context card
html += '<table style="border-collapse:collapse;width:100%;margin-bottom:16px">';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold;width:140px">Lead</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + (d.leadName || 'Unknown') + '</td></tr>';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold">Business</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + (d.businessName || 'N/A') + '</td></tr>';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold">Email</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6"><a href="mailto:' + d.senderEmail + '">' + d.senderEmail + '</a></td></tr>';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold">Industry</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + (d.industry || 'N/A') + '</td></tr>';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold">Lead ID</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + (d.leadId || 'N/A') + '</td></tr>';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold">Previous Status</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + (d.currentStatus || 'Unknown') + ' → <strong style="color:#28a745">REPLIED</strong></td></tr>';
html += '</table>';

// The actual email
html += '<h3 style="border-bottom:2px solid #dee2e6;padding-bottom:8px">Their Message</h3>';
html += '<div style="background:#f8f9fa;padding:16px;border-radius:4px;border-left:4px solid #007bff">';
if (d.htmlBody && d.htmlBody.length > 20) {
  html += d.htmlBody;
} else {
  html += '<pre style="white-space:pre-wrap;font-family:inherit">' + (d.textBody || '(empty body)') + '</pre>';
}
html += '</div>';

html += '<p style="margin-top:16px;color:#6c757d;font-size:12px">Outreach agent has been paused for this lead. Reply directly to ' + d.senderEmail + ' to continue the conversation.</p>';
html += '</div></div>';

return { json: { subject, htmlBody: html, senderEmail: d.senderEmail } };

// Format forward for unmatched sender (not in pipeline — could be new prospect)
const d = $input.item.json;

const subject = '[INBOUND EMAIL] ' + (d.senderName || d.senderEmail) + ' — ' + d.subject;

let html = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto">';
html += '<div style="background:#ffc107;color:#333;padding:12px 20px;border-radius:6px 6px 0 0">';
html += '<h2 style="margin:0">Inbound Email — Not in Pipeline</h2>';
html += '</div>';
html += '<div style="border:1px solid #dee2e6;border-top:none;padding:20px">';

html += '<table style="border-collapse:collapse;width:100%;margin-bottom:16px">';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold;width:140px">From</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + (d.senderName || 'Unknown') + ' &lt;' + d.senderEmail + '&gt;</td></tr>';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold">Subject</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + d.subject + '</td></tr>';
html += '<tr><td style="padding:6px 12px;background:#f8f9fa;border:1px solid #dee2e6;font-weight:bold">Date</td>';
html += '<td style="padding:6px 12px;border:1px solid #dee2e6">' + d.date + '</td></tr>';
html += '</table>';

html += '<h3 style="border-bottom:2px solid #dee2e6;padding-bottom:8px">Their Message</h3>';
html += '<div style="background:#f8f9fa;padding:16px;border-radius:4px;border-left:4px solid #ffc107">';
if (d.htmlBody && d.htmlBody.length > 20) {
  html += d.htmlBody;
} else {
  html += '<pre style="white-space:pre-wrap;font-family:inherit">' + (d.textBody || '(empty body)') + '</pre>';
}
html += '</div>';

html += '<p style="margin-top:16px;color:#6c757d;font-size:12px">This sender was not found in the Lead Pipeline. Could be a new prospect, vendor, or unrelated email.</p>';
html += '</div></div>';

return { json: { subject, htmlBody: html, senderEmail: d.senderEmail } };
